/**
 * Frozen snapshot of the demo traces, supplied by the team as ready-to-POST OTLP v2
 * bodies (the `trace-bodies/` dataset: a 22-span, 6-LLM-call multi-agent AI Service
 * Desk run across two tenants). Source of truth for the traces portion of `respan demo`.
 *
 * Each `body` is a complete OTLP/JSON payload for `POST /api/v2/traces`, captured
 * VERBATIM. The seeder (`seed-traces.ts`) re-stamps fresh trace/span ids and recent
 * timestamps on each fresh seed, and sets the root span's name to `workflow` (below)
 * so it shows in the dashboard Workflow column and is unique per trace — the dataset
 * repeats some scenarios with a byte-identical root span, and a unique root name keeps
 * the platform from rejecting it as a duplicate workflow span.
 *
 * The filterable `span_workflow_name` marker stays a shared constant (see seed-traces.ts)
 * so dedup, teardown, and the dashboard link match all demo traces at once.
 *
 * Frozen snapshot: not regenerated at build time, imported directly. No runtime JSON.
 */

/** A complete OTLP/JSON trace body for `POST /api/v2/traces`. */
export interface OtlpTraceBody {
  resourceSpans: Record<string, unknown>[];
}

/** One demo trace. */
export interface DemoTraceFixture {
  /** Human label for the seed summary. */
  name: string;
  /** Unique workflow id set as the root span name (shown in the Workflow column). */
  workflow: string;
  /** The OTLP body to ingest. */
  body: OtlpTraceBody;
}

